HEAD_B64 = """"""
FOOTER_B64 = """"""

def home_view(request):
    return render(request, 'index.html')


@require_POST
def contact(request):
    if request.method != "POST":
        return JsonResponse({"success": False, "message": "Зөвхөн POST хүсэлт зөвшөөрөгдөнө."}, status=405)

    print("Contact form data received : ", request.POST)
    name = request.POST.get("name", "")
    email = request.POST.get("email", "")
    phone = request.POST.get("phone", "")
    service = request.POST.get("service", "")
    message = request.POST.get("message", "")

    try:
        # EmailMessage нь reply_to-г асуудалгүй дэмжинэ
        email_message = EmailMessage(
            subject=f"KubConn Contact: {name}",
            body=f"""
            Нэр: {name}
            Email: {email}
            Утас: {phone}
            Үйлчилгээ: {service}
            Мессеж:
            {message}
            """,
            from_email=settings.DEFAULT_FROM_EMAIL,  # uuganbayarmagsar@gmail.com
            to=["uuganbayarmagsar@gmail.com"],         # Хүлээн авах мэйл
            reply_to=[email] if email else None,       # Хэрэглэгчийн мэйл рүү шууд Reply хийх боломжтой
        )
        
        ret = email_message.send(fail_silently=False)
        print("Email send result:", ret)

        return JsonResponse({
            "success": True,
            "message": "Email амжилттай илгээгдлээ."
        })

    except Exception as e:
        print("Email send error:", str(e))
        return JsonResponse({
            "success": False,
            "message": f"Мэйл илгээхэд алдаа гарлаа: {str(e)}"
        }, status=500)


def custom_404_view(request, exception=None):
    return render(request, "404.html", status=404)


def send_standard_main(self, subject, context_html, email=None, from_user=None, cc=None):

        message_template = get_template("email_master_template.html")
        message_html = message_template.render({
            "STATIC_URL": settings.STATIC_URL,
            "message": context_html,
        })

        from_email = settings.SYSTEM_FROM_EMAIL
        to = email

        msg = EmailMultiAlternatives(subject, context_html, from_email, [to], cc=cc)
        msg.attach_alternative(message_html, "text/html")

        img_header = MIMEImage(base64.b64decode(self.HEAD_B64), _subtype="png")
        img_header.add_header('Content-Disposition', "inline")
        msg.attach(img_header)

        img_footer = MIMEImage(base64.b64decode(self.FOOTER_B64), _subtype="jpg")
        img_footer.add_header('Content-Disposition', "inline")
        msg.attach(img_footer)

        msg.send()